/* Full field explanations, checked against MSC Nastran 2020 SP1 QRG.
   Pages are 1-based PDF pages. Values in examples use N, mm, s unless stated. */
(() => {
  'use strict';
  const f=(meaning,blank,example,extra={})=>({meaning,blank,example,...extra});
  const pid=(card,element,n)=>f(
    `${card}で作る「性質の設定」に付ける番号です。${element}のPID欄に同じ番号を書くと、この設定を使います。節点や要素の番号とは別の名札です。`,
    '省略できません。0より大きい整数を付けます。同じ種類の設定で番号を重複させません。',
    `${n} と書き、使う要素のPIDも ${n} にします。番号が一致することでつながります。`,{link:'basics.html#ids'});
  const mid=(example='300')=>f(
    'この断面・板・かたまりが、どの材料でできているかを材料番号で選びます。材料の名前や硬さの値を直接書く欄ではありません。',
    '省略できません。この構造解析の基本例では、別に用意したMAT1のMIDと同じ整数を書きます。',
    `${example} は「MID=${example} のMAT1を使う」という意味です。鋼という意味の固定番号ではありません。`,{link:'basics.html#ids'});
  const unspecified='この欄は2020 SP1のQRGに空欄時の数値が明記されていません。';
  const nsm=(kind)=>f(
    `強さや硬さを増やさず、重さだけを加える設定です。塗装や被覆などを簡略化する場合に使います。${kind==='line'?'棒・梁の長さ1 mm当たり':'板の面積1 mm²当たり'}の質量を書きます。材料の密度RHOとは別です。`,
    `${unspecified} 追加質量を入れないことを明確にするなら 0. と書きます。空欄から付属品の重さが自動で見積もられることはありません。`,
    kind==='line'?'0.00001 tonne/mm なら、長さ100 mmの要素に0.001 tonne（1 kg）の質量を追加します。':'0.000001 tonne/mm² なら、面積1000 mm²の要素に0.001 tonne（1 kg）の質量を追加します。',
    {unit:kind==='line'?'N・mm・s系：tonne/mm':'N・mm・s系：tonne/mm²',link:'basics.html#units'});

  const data={
    PROD:{
      rows:[['PROD','PID','MID','A','J','C','NSM','空欄','空欄','次行']],pages:[2944],
      fields:{
        PID:pid('PROD','CROD',200),MID:mid(),
        A:f('棒を長さ方向に直角に切ったときの面積です。同じ材料・長さなら、面積が大きいほど引っ張ったときに伸びにくくなります。',
          `${unspecified} 棒の断面積を必ず実数で指定します。空欄から直径や形を推測することはありません。`,
          '幅10 mm×高さ10 mmの断面なら A=100. です。直径10 mmの円なら約78.54 mm²で、10.ではありません。',{unit:'mm²'}),
        J:f('棒のねじれにくさを断面の形から表す値です。材質のねじれにくさGと組み合わせて使います。面積Aとは別物で、単位も異なります。',
          `${unspecified} 引張りだけを表す例では 0. を明示できます。ねじりを伝える棒では正しいJを入力します。`,
          '半径5 mmの丸棒なら J=π×5⁴/2 ≈ 981.75 mm⁴です。長方形ではこの丸棒の式を使えません。',{unit:'mm⁴'}),
        C:f('ねじりモーメントから、ねじりによるせん断応力を計算するための係数です。式は「せん断応力=C×ねじりモーメント/J」。材料の硬さを決める係数ではありません。',
          '既定値は0.0です。ねじり剛性Jを指定しても、C=0ならこの式で計算するねじり応力は0になります。',
          '半径5 mmの丸棒の外周応力を見るなら C=5.。Jとねじりモーメントも必要です。',{unit:'この式では長さ：mm'}),
        NSM:nsm('line')
      }
    },
    MAT1:{
      rows:[['MAT1','MID','E','G','NU','RHO','A','TREF','GE','次行'],['継続行','ST','SC','SS','MCSID','空欄','空欄','空欄','空欄','次行']],
      pages:[2242,2243,2244],layoutNote:'MAT1は、向きを変えても同じ性質を持つ材料の設定です。2行目は必要なときだけ付けます。許容応力を入れても、材料が自動で塑性変形・破断するモデルにはなりません。',
      fields:{
        MID:f('材料に付ける名札の番号です。PROD、PBAR、PSHELL、PSOLIDなどの材料欄から、この番号で呼び出します。',
          '省略できません。0より大きい整数で、他の材料と重複しない番号にします。',
          'MID=300 のMAT1に鋼の性質を入れれば、MID=300を参照する部品がその材料を使います。',{link:'basics.html#ids'}),
        E:f('ヤング率。引っ張ったり押したりしたときの「伸び縮みしにくさ」です。硬い材料ほど大きくなります。強度、つまり壊れにくさとは別です。',
          'GとNUがあれば E=2G(1+NU) から求めます。EとGを両方空欄にはできません。EとNUを同時に空欄にすると、両方0とする特殊な規則があり、普通の弾性材料の作り方には使いません。',
          'E=210000. は210000 N/mm²（210 GPa）。Gを空欄、NUを0.3にする入力ができます。',{unit:'N/mm² = MPa'}),
        G:f('せん断弾性係数。四角い小片をひし形のようにずらす変形や、棒のねじれに対する硬さです。ヤング率Eとは役割が違います。',
          'EとNUがあれば G=E/[2(1+NU)] から計算されます。EとGを両方空欄にはできません。GとNUを同時に空欄にすると、両方0とする特殊な規則になるので、ねじりを考えるモデルで使わないでください。',
          'E=210000.、NU=0.3、Gは空欄なら、Gは約80769.23 N/mm²になります。',{unit:'N/mm² = MPa'}),
        NU:f('ポアソン比。棒を縦に引くと横が細くなる、その「横の縮む割合÷縦の伸びる割合」を表します。長さの比なので単位はありません。',
          'EとGがあれば NU=E/(2G)−1 から計算します。EまたはGも一緒に空欄にすると0とする特殊規則になります。通常はEとNUを入力し、Gだけを空欄にすると分かりやすくなります。',
          'NU=0.3 の材料が長さ方向に0.1%伸びると、横方向には約0.03%縮みます。自由に横へ縮める一様な引張りの例です。',{unit:'単位なし',tip:'通常の安定した等方弾性材料では −1 < NU < 0.5。0.5をそのまま入れないでください。'}),
        RHO:f('質量密度。体積1 mm³に、どれだけの質量が入っているかです。自重の計算や振動の計算に使います。重力の強さや重さNを入れる欄ではありません。',
          `${unspecified} 空欄から材料の密度は自動で調べられません。自重や固有振動を計算するなら、単位をそろえた密度を必ず入力します。質量を使わない教材の引張り例では省いています。`,
          '鋼の密度を7850 kg/m³とすると、N・mm・s系では7.85E-9 tonne/mm³です。7850をそのまま入れると単位が合いません。',{unit:'N・mm・s系：tonne/mm³',link:'basics.html#units'}),
        A:f('線膨張係数。温度が1度上がったとき、元の長さに対してどのくらい伸びるかを表します。PRODのA（面積）とは同じ文字でも意味が違います。',
          `${unspecified} 温度による伸び縮みを計算するなら値を入力します。この教材の温度荷重を使わない引張り例では省いています。`,
          'A=1.2E-5、温度上昇100度、長さ1000 mmなら、自由に伸びられる棒の伸びは1.2 mmです。',{unit:'1/K、または温度差1℃当たり'}),
        TREF:f('熱で伸びた量を測るための基準温度です。「何度の状態を伸び0とするか」を決めます。現在の温度そのものを指定する欄ではありません。',
          'Aを指定した場合の既定値は0.0です。SOL 101などでTEMPERATURE(INITIAL)を基準温度として使う場合は、TREFを空欄にします。SOL 106では用途が異なります。',
          'TREF=20.、与える温度=80. なら、温度差60度に対応する熱膨張を計算します。',{unit:'解析で統一した温度の単位'}),
        GE:f('構造減衰の係数。振動のエネルギーが失われる性質を表す値です。静止した状態の伸び縮みを計算するSOL 101の基本例では使いません。',
          `${unspecified} 減衰を与えないことを明確にするなら0.を入力します。振動解析で使うときは、解析法がこの係数をどのように使うかも確認します。`,
          'GE=0.04 は、対応する条件では臨界減衰比2%の2倍です。静解析の応力を4%減らす指定ではありません。',{unit:'単位なし'}),
        ST:f('引張りの許容応力。計算された引張応力と比べて、余裕があるかを評価するための上限値です。対応する一部の要素で安全余裕の計算に使います。',
          '任意項目です。空欄なら、この欄による引張りの許容値を指定しません。材料のヤング率や変位の計算は変わりません。',
          'ST=250. は引張りの許容値250 MPa。実際に250 MPaで自動破断させる指定ではありません。',{unit:'N/mm² = MPa'}),
        SC:f('圧縮の許容応力。押し縮められるときの評価用の上限を、正の大きさで書きます。計算結果の圧縮応力が負でも、この入力は正です。',
          '任意項目です。空欄なら、この欄による圧縮の許容値を指定しません。負号を付けて入力する欄ではありません。',
          '圧縮側の許容値が200 MPaなら SC=200.。SC=-200.とはしません。',{unit:'N/mm² = MPa'}),
        SS:f('せん断の許容応力。面に沿ってずらす応力に対する評価用の上限を、正の大きさで書きます。',
          '任意項目です。空欄なら、この欄によるせん断の許容値を指定しません。',
          'せん断の許容値が140 MPaなら SS=140.。採用する材料・評価基準に合わせて決めます。',{unit:'N/mm² = MPa'}),
        MCSID:f('PARAM CURVを使った特殊なシェルの節点応力・ひずみ処理で参照する座標系番号です。MAT1全体の応力方向を一括変更する一般的なスイッチではありません。',
          'CURVを使わない通常の例では空欄です。CURVの該当処理を使う場合は、0ではない定義済みの座標系番号が必要です。',
          '対象の曲面処理用に座標系10を定義しているなら10を指定します。通常のソリッド応力軸はPSOLIDのCORDMを確認します。',{link:'coordinates.html#elements'})
      }
    },
    PBAR:{
      rows:[['PBAR','PID','MID','A','I1','I2','J','NSM','空欄','次行'],['継続行','C1','C2','D1','D2','E1','E2','F1','F2','次行'],['継続行','K1','K2','I12','空欄','空欄','空欄','空欄','空欄','次行']],
      pages:[2726,2727],layoutNote:'1行目は梁の断面の性質、2行目は応力を見る断面内の位置、3行目は横せん断と断面の連成です。2行目・3行目は省略できますが、必要な項目の行位置を前に詰めてはいけません。',
      fields:{
        PID:pid('PBAR','CBAR',210),MID:mid(),
        A:f('梁を長さ方向に直角に切った断面の面積です。軸方向の伸びにくさや、材料の密度から求める質量に関係します。',
          '既定値は0.0です。空欄だと通常の梁の断面積は与えられません。実際の梁では正しい面積を入力します。',
          '10 mm×10 mmの正方形なら100.、10 mm×20 mmなら200.です。',{unit:'mm²'}),
        I1:f('断面二次モーメント。梁が要素y方向にたわむ曲げ（x–y平面）への抵抗を表します。断面の面積がy方向に中心から遠く分布するほど大きくなります。材料の硬さEとは別に、形の効果を表す値です。',
          '既定値は0.0です。この方向の曲げ剛性を与えないことになるため、通常の梁では値を入力します。',
          '要素y方向の高さ20 mm、z方向の幅10 mmの長方形なら I1=10×20³/12 ≈ 6666.67 mm⁴です。',{unit:'mm⁴',tip:'PBARではI1=要素z軸まわりの面積二次モーメントです。「1だからx軸まわり」と考えないでください。'}),
        I2:f('もう一方の断面二次モーメント。梁が要素z方向にたわむ曲げ（x–z平面）への抵抗を表します。同じ断面でもI1とI2は異なることがあります。',
          '既定値は0.0です。この方向の曲げ剛性を与えません。両方向に曲げを受ける梁では、I1とI2の両方を入力します。',
          'y方向20 mm、z方向10 mmの長方形なら I2=20×10³/12 ≈ 1666.67 mm⁴です。向きを90度変えるとI1とI2の役割が入れ替わります。',{unit:'mm⁴'}),
        J:f('梁のねじりに対する断面の性質です。棒を雑巾のようにねじる変形の硬さに関係します。I1やI2をそのまま足せば常に求まるわけではありません。',
          'SOL 101を含む通常の解析の既定値は0.0です。ねじり剛性を与えません。SOL 600では既定値が(I1+I2)/2と異なります。',
          '一辺10 mmの正方形断面ならJは約1406 mm⁴です。I1+I2≈1666.67 mm⁴をそのまま使う値ではありません。',{unit:'mm⁴'}),
        NSM:nsm('line'),
        K1:f('1方向の横せん断によるたわみを調整する係数です。断面がずれるような変形を、K1×A×Gという硬さで計算します。長い細い梁より、短く厚い梁で影響が出やすくなります。',
          '既定値は無限大です。「せん断の硬さが0」ではなく、この方向の横せん断によるたわみを0とする扱いです。A=0なら必ず空欄にします。I12≠0の場合はK1・K2は使われません。',
          '単純な長方形の近似では0.833333（5/6）がよく使われます。実際の断面に合う係数を選びます。',{unit:'単位なし'}),
        K2:f('2方向の横せん断によるたわみを調整する係数です。K2×A×Gが、この方向のせん断の硬さに関係します。',
          '既定値は無限大で、この方向の横せん断によるたわみを考えません。A=0なら空欄。I12≠0ならK1・K2は使われません。',
          '1方向と同じ長方形近似を使うならK2も0.833333。K1と同じ値を必ず使う規則ではありません。',{unit:'単位なし'}),
        I12:f('断面相乗モーメント。断面の形と軸の向きによって、2つの曲げ方向が結び付く度合いを表します。断面の主軸に合わせれば0になります。',
          '既定値は0.0で、この項による2方向の曲げの結び付きを与えません。正しい断面軸で0とできるかを確認します。',
          '中心を通る辺に平行な軸を使った長方形断面なら0.です。非対称断面では、自動的に0になるとは限りません。',{unit:'mm⁴',tip:'通常の断面ではI1×I2>I12²が必要です。符号も断面軸の定義に合わせます。'})
      }
    },
    PSHELL:{
      rows:[['PSHELL','PID','MID1','T','MID2','12I/T³','MID3','TS/T','NSM','次行'],['継続行','Z1','Z2','MID4','空欄','空欄','空欄','空欄','空欄','次行']],pages:[2955,2956,2958,2959],
      layoutNote:'シェルは薄い板を面で表す要素です。面内に伸びる働き、曲がる働き、厚さ方向にずれる働きを分けて設定します。同じ材料の普通の板でも、使う働きのMID欄を明示します。',
      fields:{
        PID:pid('PSHELL','CQUAD4・CTRIA3',601),
        MID1:f('板が面内で伸び縮みしたり、面内でずれたりするときに使う材料番号です。この「面内の働き」を膜（まく）と呼びます。',
          '面内の剛性と、このMIDによる膜・曲げの結び付きを与えません。「MID2と同じ材料で面内も計算する」という意味ではありません。質量計算の密度は、MID1が空欄ならMID2の材料から取得します。',
          '面内にも曲げにも同じMAT1 300を使う板なら、MID1=300、MID2=300と入力します。',{link:'basics.html#ids'}),
        T:f('板の厚さです。シェルではGRIDを結んだ面に厚さを持たせるため、この値を使います。要素側に個別の厚さTiがあれば、その指定も関係します。',
          '空欄にする場合は、CQUAD4やCTRIA3などのTi欄で厚さを指定する必要があります。両方を空欄にしても、図から厚さを読み取ってくれません。',
          '厚さ2 mmの板なら2.です。TFLAG=1で要素側Ti=0.5なら、その節点での厚さはT×0.5になります。',{unit:'mm'}),
        MID2:f('板がたわんで曲がるときに使う材料番号です。薄い下敷きを曲げるような動きを担当します。',
          '曲げ剛性、膜・曲げの結び付き、横せん断の剛性を与えません。面内だけの膜要素を作るときは空欄にできます。普通の曲がる板では入力します。',
          'MAT1 300の普通の板なら300。特別な値−1は平面ひずみ解析用で、通常の曲がるシェルとは別のモデルです。',{link:'basics.html#ids',tip:'MID2を空欄または−1にするときは、MID3も空欄にします。'}),
        '12I/T³':f('普通の均質な板に比べて、曲げに関わる断面の性質を何倍にするかを表す比です。均質とは、厚さ方向に同じ材料が続いていることです。',
          '既定値は1.0です。厚さTの均質な板として計算します。空欄だから曲げを無視するわけではありません。',
          '1.なら通常の均質板。2.ならこの曲げに関する比を2倍にしますが、厚さTや面内の硬さを直接2倍にする指定ではありません。',{unit:'単位なし'}),
        MID3:f('板の厚さ方向の線が、板に対して斜めになるような「横せん断」の変形に使う材料番号です。板がずれながらたわむ柔らかさに関係します。',
          '横せん断によるたわみ（柔性）を0として扱います。「横せん断の剛性が0で、自由にずれる」という意味ではありません。',
          'MID1=300、MID2=300、MID3=300なら、同じ材料で面内・曲げ・横せん断を設定します。MID2が空欄または−1ならMID3は空欄です。'),
        'TS/T':f('横せん断に対して有効に働く厚さTsと、板厚Tとの比です。厚さの中でせん断応力が一様でないことを、簡単な係数で表します。',
          '既定値は0.833333、約5/6です。MID3を使う均質な板の標準的な値です。',
          '厚さ2 mmでTS/T=0.833333なら、せん断に用いる有効厚さの考え方は約1.667 mmです。実物の板厚Tが変わるわけではありません。',{unit:'単位なし'}),
        NSM:nsm('area'),
        Z1:f('1つ目の応力を調べる位置です。基準面から要素の法線方向へ、どれだけ離れたところを見るかを書きます。負の位置は「圧縮」という意味ではありません。',
          '既定値は−T/2です。ここでのTは、要素側の厚さ指定も反映した局所の板厚です。通常は板の−側表面になります。',
          '厚さ2 mm・オフセットなしなら、空欄は−1 mmの位置を表します。そこで引張りが生じれば応力は正です。',{unit:'mm',link:'coordinates.html#shell'}),
        Z2:f('2つ目の応力を調べる位置です。Z1と対になる別の位置を指定して、曲げによる表裏の応力の違いを見ます。',
          '既定値は+T/2です。通常の均質板では+側表面を調べます。',
          '厚さ2 mm・オフセットなしなら、空欄は+1 mm。Z1とZ2を別の距離に指定して、板厚内の位置を見ることもできます。',{unit:'mm',link:'coordinates.html#shell'}),
        MID4:f('板を引くと曲がる、曲げると面内に伸びる、といった「膜と曲げの結び付き」を別に定義する材料番号です。基本的な均質板では通常使いません。',
          'このMID4による結び付きは与えません。ただし、要素側のZOFFSによる位置のずれから結び付きが生じる場合はあります。',
          '中立面の上下で対称な普通の板なら空欄です。使用する場合は専用に用意した別材料番号を指定し、MID1・MID2と同じ番号にはできません。',
          {tip:'MID1とMID2の両方が正の材料番号でなければMID4は空欄にします。MID4とZOFFSを両方指定すると効果が重なるため、同じずれを二重に与えないようにします。'})
      }
    },
    PSOLID:{
      rows:[['PSOLID','PID','MID','CORDM','IN','STRESS','ISOP','FCTN','空欄','次行']],pages:[2976,2977,2978,2979,2980],
      layoutNote:'以下の既定値の説明は、通常のSOL 101の構造用ソリッドを対象にしています。要素の種類と中間節点の有無で変わる欄があります。計算法を変えるときはIN・STRESS・ISOPを組として確認します。',
      fields:{
        PID:pid('PSOLID','CTETRA・CHEXA',801),MID:mid(),
        CORDM:f('材料の方向と、応力の成分を読む軸に関わる座標系番号です。節点の位置を決めるGRIDのCPとは別です。方向により性質が違うMAT9では、剛性にも影響します。',
          '通常は0、基本座標系です。ただしNASTRAN文のCORDM指定で既定値を変更できます。0を明示すると基本座標系を指定できます。',
          '0なら基本X・Y・Z。10なら定義済み座標系10。−1は偏りを避ける内部の要素座標系、−2は要素の座標系を選ぶ特別な指定です。',{link:'coordinates.html#elements'}),
        IN:f('要素の内部で、計算用の点をどのように置くかを選びます。体積全体の働きを、いくつかの点で計算してまとめる方法です。単に「点が多いほど必ず正確」ではありません。',
          '8節点CHEXAはBUBBLE（2×2×2と補正）。中間節点のあるCHEXAはTHREE（3×3×3）。4節点CTETRAはTWOの表記で1点、中間節点のあるCTETRAはTHREEの表記で5点が基本の既定です。',
          '8節点CHEXAの基本例では空欄を使います。CTETRAでTWOと書いても「2点」の意味ではなく、選択肢の名前です。',
          {tip:'BUBBLEは要素内部の変形を補う方法の名前です。CTETRAや中間節点のあるCHEXAに、そのまま指定する選択肢ではありません。'}),
        STRESS:f('要素内のどの場所の応力を出すかを選びます。GRIDは節点位置へ評価した値、GAUSSは計算用の積分点の値です。出力を要求するCase ControlのSTRESSとは役割が違います。',
          '既定値はGRIDです。これは隣接要素同士の応力を自動で平均する指定ではありません。',
          '8節点CHEXAではGAUSS（または1）で積分点出力を選べます。中間節点のあるCHEXAでは同じGAUSS選択は使えません。CTETRAは一次・二次ともGAUSSを選べます。'),
        ISOP:f('要素内部の計算をまとめる「積分方法」を選びます。REDUCEDはせん断の計算を調整して、実物より不自然に硬くなる現象を減らす方法です。FULLは標準の方法です。',
          '通常の構造用CHEXA・CPENTAはREDUCED、CTETRAはFULLです。空欄が全要素で同じ計算法を意味するわけではありません。',
          'SOL 101の8節点CHEXAでINとISOPを空欄にすると、標準推奨のBUBBLEとREDUCEDの組になります。',
          {tip:'使えないIN・STRESS・ISOPの組合せを指定すると、警告とともに既定の組へ戻されることがあります。'}),
        FCTN:f('この要素を、構造のかたまりとして使うか、流体などの特別なモデルとして使うかを選びます。',
          '既定値はSMECHです。通常の構造要素として扱います。',
          '鋼のかたまりならSMECHまたは空欄。PFLUIDは流体、FFLUIDは周波数依存の吸収特性を持つ流体、POROは多孔質媒体です。材料カードも対応するものが必要です。',
          {tip:'PFLUID・FFLUIDはMAT10、POROはMATPE1を参照します。普通のMAT1のまま文字だけ変えても、正しい流体モデルにはなりません。'})
      }
    },
    PARAM:{
      rows:[['PARAM','N','V1','V2','空欄','空欄','空欄','空欄','空欄','次行']],pages:[2717,1000,1007,1008],
      layoutNote:'PARAMの欄の意味は共通ですが、値の型・既定値・効果はパラメータ名ごとに決まります。この教材は代表例POSTとOMIDを説明します。全パラメータ名を網羅する一覧ではありません。',
      fields:{
        N:f('変更したい設定の名前です。1〜8文字の英数字で、最初は英字です。ID番号ではなく、決められた名前をそのまま書きます。',
          '省略できません。名前がなければ、何の設定を変更するのか分かりません。',
          'POSTは後処理用ファイルの設定、OMIDは対象シェルのF06/PCHを材料座標で出すかどうかの設定です。'),
        V1:f('Nで選んだ設定の値です。整数・実数・文字のどれを書くかはNによって違います。値を変えると何が変わるかを、設定名とセットで読みます。',
          '空欄なら常に0になるわけではありません。必要な値を明示します。PARAM行そのものを省く場合の既定値は、POSTが9999999、OMIDがNOです。「V1だけ空欄」と「カードなし」を同じと決めつけないでください。',
          'POSTなら−1や1という整数を指定してOP2出力を設定します。OMIDならYESと書きます。OMIDのYESはOP2/XDBの座標を変更しません。',
          {tip:'2020 SP1のQRGは、新しい結果ブロックにはPOST=1を案内しています。既存例のPOST=−1は互換用途の一例です。',link:'coordinates.html#shell'}),
        V2:f('1つの値だけでは足りない設定に使う2つ目の欄です。複素数の設定なら、V1が実部、V2が虚部になります。すべてのPARAMに必要な欄ではありません。',
          'POSTやOMIDのような整数・文字の設定では、V2は空欄にします。複素数型などでは、そのパラメータの型と空欄規則に従います。',
          'PARAMのN=POST、V1=−1の例ではV2は空欄。余った欄に別の設定名を書き足すことはできません。')
      }
    },
    MDLPRM:{
      rows:[['MDLPRM','PARAM1','VAL1','PARAM2','VAL2','PARAM3','VAL3','PARAM4','VAL4','次行']],pages:[2487,2488,2489],
      layoutNote:'「設定名、値」を2欄で1組として並べます。続きの行にも組を追加できます。複数のMDLPRM行は使えますが、同じ設定名を重複して定義することはできません。',fields:{}
    }
  };
  for(const [point,y,z] of [['C',5,5],['D',-5,5],['E',-5,-5],['F',5,-5]]){
    for(const [suffix,axis,val] of [['1','y',y],['2','z',z]]){
      const key=point+suffix;
      data.PBAR.fields[key]=f(
        `梁の断面で応力を見る点${point}の、要素${axis}方向の位置です。${point}1と${point}2の2つを組にして、断面の中の1点を決めます。節点番号ではなく、断面の原点からの距離です。`,
        `既定値は0.0です。${key}を空欄にすると、その点の${axis}座標は0になります。全て空欄ならC〜Fが断面原点に重なり、表面の曲げ応力を見逃すことがあります。`,
        `一辺10 mm、中心を原点とする正方形の例では${point}1=${y}.、${point}2=${z}.。${key}には${val}.を入れます。`,
        {unit:'mm',tip:'通常のSOL 101のCBARでは、C〜Fの列は曲げ応力です。軸応力は別の列で出ます。合成応力を見るときは両者を合わせます。',link:'coordinates.html#elements'});
    }
  }
  for(let i=1;i<=4;i++){
    data.MDLPRM.fields['PARAM'+i]=f(
      `${i}組目の設定名です。そのすぐ右のVAL${i}と対にして使います。PARAMカードのNと似ていますが、使える設定名の一覧は別です。`,
      i===1?'設定を1つ以上書きます。何も設定しないならMDLPRM行自体が不要です。':'この組を追加しないなら、設定名と値の両方を空欄にします。名前だけを書いて値を抜かないでください。',
      i===1?'HDF5 は結果をHDF5形式のファイルに保存する設定です。次のVAL1に値を書きます。':`例えば別の出力設定を追加するときに使います。同じHDF5を${i}回目として重複入力する欄ではありません。`);
    data.MDLPRM.fields['VAL'+i]=f(
      `左隣のPARAM${i}で選んだ設定の値です。整数か実数か、何を意味する数かは、その設定名で決まります。`,
      `PARAM${i}も空欄ならこの組はありません。設定名を入力した組では、必要な値を明示します。HDF5を指定しない場合の既定値は−1で、HDF5データベースを作りません。`,
      'HDF5なら0は圧縮なし、1は圧縮ありで出力。2は入力データを含めず圧縮なし、3は入力データを含めず圧縮あり。圧縮はファイルを小さくする保存方法です。');
  }
  data.MDLPRM.fields['追加のPARAMi / VALi']=f(
    '5組目以降の設定も、設定名と値を対にして継続行へ書けます。各行の第1欄と第10欄は、データではなく行をつなぐために使います。',
    '設定を追加しなければ、継続行自体が不要です。既に書いた設定と同名の設定は繰り返せません。',
    '1行で足りなければ、次行第2欄から次の設定名、その右の欄に値、と続けます。',{position:'2行目以降の第2〜9欄を、2欄ずつ組にする'});
  window.FIELD_GUIDE=Object.assign(window.FIELD_GUIDE||{},data);
})();
